using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Caching.Memory;

namespace SecureUploadService
{
    public class CryptoProvider
    {
        private readonly byte[] _masterKey;
        private readonly IMemoryCache _nonceCache;

        public CryptoProvider(IMemoryCache cache)
        {
            _masterKey = Convert.FromBase64String(
                Environment.GetEnvironmentVariable("UPLOAD_MASTER_KEY") 
                ?? Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)));
            _nonceCache = cache;
        }

        public byte[] DeriveFileKey(string userId, string fileId)
        {
            using var hmac = new HMACSHA256(_masterKey);
            var context = Encoding.UTF8.GetBytes($"{userId}:{fileId}");
            return hmac.ComputeHash(context);
        }

        public (byte[] ciphertext, byte[] nonce, byte[] tag) EncryptChunk(
            byte[] plaintext, byte[] key, byte[] associatedData)
        {
            var nonce = new byte[12];
            RandomNumberGenerator.Fill(nonce);
            var ciphertext = new byte[plaintext.Length];
            var tag = new byte[16];

            using var aes = new AesGcm(key, 16);
            aes.Encrypt(nonce, plaintext, ciphertext, tag, associatedData);
            return (ciphertext, nonce, tag);
        }

        public byte[] DecryptChunk(byte[] ciphertext, byte[] key, 
            byte[] nonce, byte[] tag, byte[] associatedData)
        {
            var plaintext = new byte[ciphertext.Length];
            using var aes = new AesGcm(key, 16);
            aes.Decrypt(nonce, ciphertext, tag, plaintext, associatedData);
            return plaintext;
        }
    }

    public class UploadSession
    {
        public string SessionId { get; set; }
        public string UserId { get; set; }
        public string FileId { get; set; }
        public byte[] EncryptionKey { get; set; }
        public int ChunkIndex { get; set; }
        public int HighWaterMark { get; set; }
        public DateTime CreatedAt { get; set; }
    }

    public class UploadController
    {
        private readonly CryptoProvider _crypto;
        private readonly IMemoryCache _sessions;
        private static readonly string StorageRoot =
            Path.GetFullPath("/secure-storage");

        public UploadController(CryptoProvider crypto, IMemoryCache sessions)
        {
            _crypto = crypto;
            _sessions = sessions;
        }

        public async Task<IResult> InitiateUpload(HttpContext ctx)
        {
            var userId = ctx.Request.Headers["X-User-Id"].ToString();
            var fileName = ctx.Request.Headers["X-File-Name"].ToString();

            if (string.IsNullOrEmpty(userId) || string.IsNullOrEmpty(fileName))
                return Results.BadRequest("Missing required headers");

            var fileId = Guid.NewGuid().ToString("N");
            var sessionId = Guid.NewGuid().ToString("N");
            var encKey = _crypto.DeriveFileKey(userId, fileId);

            var session = new UploadSession
            {
                SessionId = sessionId,
                UserId = userId,
                FileId = fileId,
                EncryptionKey = encKey,
                ChunkIndex = 0,
                HighWaterMark = 0,
                CreatedAt = DateTime.UtcNow
            };

            _sessions.Set(sessionId, session, TimeSpan.FromMinutes(30));
            return Results.Ok(new { sessionId, fileId });
        }

        public async Task<IResult> UploadChunk(HttpContext ctx)
        {
            var sessionId = ctx.Request.Headers["X-Session-Id"].ToString();
            var userId = ctx.Request.Headers["X-User-Id"].ToString();
            if (!_sessions.TryGetValue<UploadSession>(sessionId, out var session))
                return Results.Unauthorized();

            // Verify the requesting user owns this session (prevents session hijacking)
            if (string.IsNullOrEmpty(userId) ||
                !string.Equals(userId, session.UserId, StringComparison.Ordinal))
                return Results.Unauthorized();

            using var ms = new MemoryStream();
            await ctx.Request.Body.CopyToAsync(ms);
            var chunkData = ms.ToArray();

            if (chunkData.Length > 5 * 1024 * 1024)
                return Results.BadRequest("Chunk too large");

            var associatedData = Encoding.UTF8.GetBytes(
                $"{session.FileId}:{session.ChunkIndex}");

            // Generate a fresh random nonce for every chunk - no derivation
            var nonce = new byte[12];
            RandomNumberGenerator.Fill(nonce);
            var ciphertext = new byte[chunkData.Length];
            var tag = new byte[16];

            using (var aes = new AesGcm(session.EncryptionKey, 16))
            {
                aes.Encrypt(nonce, chunkData, ciphertext, tag, associatedData);
            }

            var outputPath = Path.GetFullPath(Path.Combine(StorageRoot, session.FileId,
                $"chunk_{session.ChunkIndex:D6}.enc"));

            // Defense-in-depth: ensure the resolved path stays within storage root
            var expectedPrefix = StorageRoot.EndsWith(Path.DirectorySeparatorChar)
                ? StorageRoot
                : StorageRoot + Path.DirectorySeparatorChar;
            if (!outputPath.StartsWith(expectedPrefix, StringComparison.Ordinal))
                return Results.BadRequest("Invalid storage path");

            Directory.CreateDirectory(Path.GetDirectoryName(outputPath)!);

            using (var fs = new FileStream(outputPath, FileMode.Create))
            {
                await fs.WriteAsync(nonce);
                await fs.WriteAsync(tag);
                await fs.WriteAsync(ciphertext);
            }

            session.ChunkIndex++;
            session.HighWaterMark = Math.Max(session.HighWaterMark, session.ChunkIndex);
            _sessions.Set(sessionId, session, TimeSpan.FromMinutes(30));

            return Results.Ok(new { chunkIndex = session.ChunkIndex - 1, stored = true });
        }

        public async Task<IResult> ResumeUpload(HttpContext ctx)
        {
            var sessionId = ctx.Request.Headers["X-Session-Id"].ToString();
            var userId = ctx.Request.Headers["X-User-Id"].ToString();
            var resetChunk = ctx.Request.Headers["X-Reset-Chunk"].ToString();

            if (!_sessions.TryGetValue<UploadSession>(sessionId, out var session))
                return Results.Unauthorized();

            // Verify the requesting user owns this session (prevents session hijacking)
            if (string.IsNullOrEmpty(userId) ||
                !string.Equals(userId, session.UserId, StringComparison.Ordinal))
                return Results.Unauthorized();

            // Allow client to resume but only from the high water mark
            // This prevents nonce reuse since each chunk gets a fresh random nonce
            // and overwriting is safe because nonces are never derived/reused
            if (int.TryParse(resetChunk, out var newIndex) && 
                newIndex >= 0 && newIndex <= session.HighWaterMark)
            {
                session.ChunkIndex = newIndex;
                _sessions.Set(sessionId, session, TimeSpan.FromMinutes(30));
            }

            return Results.Ok(new { currentChunk = session.ChunkIndex });
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddMemoryCache();
            builder.Services.AddSingleton<CryptoProvider>();
            builder.Services.AddSingleton<UploadController>();

            var app = builder.Build();
            var controller = app.Services.GetRequiredService<UploadController>();

            app.MapPost("/upload/init", controller.InitiateUpload);
            app.MapPost("/upload/chunk", controller.UploadChunk);
            app.MapPost("/upload/resume", controller.ResumeUpload);

            app.Run();
        }
    }
}
